//————————————————————————————————————————————— letterPoint 
class letterPoint {
  constructor(idx, x, y) {
    this.idx = idx;
    this.pos = createVector(x, y, 0)
    this.r = _r
    this.mass = random(5, 100)
  }

  //————————————————————————————————————————————— letterPoint attract
  attract(mover) {
    let force = p5.Vector.sub(this.pos, mover.pos)
    let distanceSq = constrain(force.magSq(), width / 100, width)
    let G = 10;
    let str = G * (this.mass * mover.mass) / float(distanceSq)
    force.setMag(str)
    force.limit(_maxForce);
    mover.applyForce(force)
  }


  //————————————————————————————————————————————— letterPoint show
  show() {
    push()
    translate(this.pos.x, this.pos.y)
    noStroke()
    fill(_clrs[2])
    if (this.active) ellipse(0, 0, this.r * 4, this.r * 4)
    else ellipse(0, 0, this.r, this.r)
    pop()
  }
}

// === Tab: mypoint ===
//————————————————————————————————————————————— myPoint 
class myPoint {
  constructor(idx, x, y, letter) {
    this.idx = idx;
    this.pos = createVector(x, y, 0)
    this.vel = createVector(0, 0, 0)
    this.acc = createVector(0, 0, 0)

    this.trail = []
    this.totalTrail = floor(random(1, _totaltrail))
    this.r = _r
    this.mass = 1
    this.count = 0

    this.attractors = []
    for (let i = 0; i < 2; i++) {
      const randPoint = pickRandPoint(letter)
      this.attractors.push(randPoint)
    }
  }

  //————————————————————————————————————————————— myPoint forces
  updateForce() {
    // divide based on the forces included
    this.acc.div(this.count)

    this.vel.add(this.acc)
    this.vel.limit(_maxSpeed);
    this.pos.add(this.vel)
    this.acc.mult(0)

    // reset count
    this.count = 0
  }

  repulse(other) {
    let opposite = p5.Vector.sub(this.pos, other.pos);
    const d = opposite.mag();
    if (d < _repulsionDistance) {
      // opposite.normalize()
      opposite.limit(_maxForce)
      this.applyForce(opposite)
      return d
    }
    return d
  }

  applyForce(force) {
    const f = p5.Vector.div(force, this.mass)
    this.acc.add(f)
    this.count++
  }

  arrive(target) {
    var desired = p5.Vector.sub(target, this.pos);
    var d = desired.mag();
    var speed = _maxSpeed;
    if (d < 100) {
      speed = map(d, 0, 100, 0, _maxSpeed);
    }
    desired.setMag(speed);
    var steer = p5.Vector.sub(desired, this.vel);
    steer.limit(_maxForce);
    return steer;
  }

  //————————————————————————————————————————————— myPoint addTrail
  addTrail() {
    if (this.trail.length > this.totalTrail * _trailInteractive) {
      const diff = ceil(this.trail.length - this.totalTrail * _trailInteractive)
      this.trail.splice(0, diff)
    }
    this.trail.push(this.pos.copy())

  }

  //————————————————————————————————————————————— myPoint show
  show() {
    push()
    noFill()
    strokeWeight(_sw)
    stroke(_clrs[1])
    beginShape()
    this.trail.forEach((elm, idx) => {
      vertex(elm.x, elm.y)
    })
    endShape()

    // noStroke()
    fill(_clrs[1])
    ellipse(this.pos.x, this.pos.y, this.r, this.r)

    pop()
  }
}

function pickRandPoint(idx) {
  return random(_points[idx])
}

